    for _ in range(10000):
        G = nx.Graph()
        G.add_nodes_from(range(n))
        edges = []

        # Try to add edges
        possible_edges = []
        for i in range(n):
            for j in range(i + 1, n):
                possible_edges.append((i, j))
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            G.add_edge(u, v)
            if not is_girth_at_least_7(G):
                G.remove_edge(u, v)
            else:
                edges.append((u, v))

            if len(edges) >= 26:
                # Check 3-colorability
                if nx.is_colorable(G, 3):
                    return edges

    return None

